"""Builds content_EN/FR/NL/DE.json for the Meal Planner manual from ONE structure.

The structure (headings, figures, tables, boxes, page breaks) is defined once in `blocks()`.
Each language only supplies its texts in a dictionary, so the four manuals cannot drift apart.
App button names are copied from the app's own I18N texts (app/index.html) per language.
Netlify's screens exist in English only: Netlify button names stay English in every language.

Run:  py manual/content_build.py   -> manual/content_XX.json  (then build each with build_with_toc.py)
"""
import json
import re
from pathlib import Path

HERE = Path(__file__).parent


def blocks(T, L):
    f = lambda name: f"figures/{L}/{name}"          # language-specific figure
    nf = lambda name: f"figures/netlify/{name}"     # Netlify: shared (English UI)
    h1 = lambda k: {"type": "h1", "text": T[k]}
    h2 = lambda k: {"type": "h2", "text": T[k]}
    p = lambda k: {"type": "p", "text": T[k]}
    nums = lambda k: {"type": "numbers", "items": T[k]}
    box = lambda v, k: {"type": "callout", "variant": v, "title": T[k][0], "text": T[k][1]}
    fig = lambda path, w, k: {"type": "figure", "path": path, "width": w, "caption": T[k][0], "alt": T[k][1]}
    tab = lambda k, widths: {"type": "table", "header": T[k][0], "widths": widths, "rows": T[k][1]}
    return [
        h1("h_howto"), p("howto1"), p("howto2"), tab("t_boxes", [1, 5]), p("howto3"),
        h2("h_glance"), fig(f("fig_week.png"), 230, "fig1"), tab("t_glance", [1, 3, 9]),

        h1("h_quick"), p("quick_purpose"), nums("quick_steps"),
        fig(f("fig_add_meal.png"), 470, "fig2"), p("quick_success"), box("tip", "c_photo"),

        h1("h_week"), p("week_purpose"),
        h2("h_week_nav"), nums("week_nav_steps"),
        h2("h_week_quick"), p("week_quick_p"), nums("week_quick_steps"),
        fig(f("fig_day.png"), 250, "fig3"), p("week_quick_success"),
        h2("h_week_change"), tab("t_change", [2, 3]), box("trap", "c_bin"),

        h1("h_ai"), p("ai_purpose"), p("ai_need"), nums("ai_steps"),
        fig(f("fig_plan.png"), 440, "fig4"), p("ai_success"),
        box("trap", "c_replace"), box("tip", "c_again"), box("note", "c_lang"),

        h1("h_shop"), p("shop_purpose"), fig(f("fig_shop.png"), 230, "fig5"), tab("t_shop", [1, 4, 8]),
        h2("h_shop_ai"), nums("shop_ai_steps"), p("shop_ai_success"),
        box("note", "c_which_week"), box("tip", "c_list_after"),

        h1("h_dish"), p("dish_purpose"), nums("dish_steps"),
        fig(f("fig_identify.png"), 320, "fig6"), p("dish_success"),
        box("note", "c_basics"), box("tip", "c_editor"),

        h1("h_settings"), p("settings_purpose"), fig(f("fig_menu.png"), 250, "fig7"),
        h2("h_lang"), nums("lang_steps"), p("lang_p"),
        h2("h_family"), nums("family_steps"), p("family_p"),
        h2("h_pin"), nums("pin_steps"), box("trap", "c_pin"),
        h2("h_service"), p("service_p"),

        h1("h_backup"), p("backup_purpose"), box("note", "c_data_phone"),
        h2("h_backup_make"), nums("backup_steps"), p("backup_file"),
        h2("h_restore"), nums("restore_steps"), tab("t_restore", [2, 3]),
        box("trap", "c_clear"), box("tip", "c_weekly"),

        h1("h_problems"), tab("t_problems", [2, 3]),

        h1("h_appA"), p("appA_purpose"), p("appA_need"), nums("appA_steps"),
        fig(f("fig_lock.png"), 200, "fig8"), p("appA_success"),
        box("note", "c_key_phone"), box("trap", "c_key_private"),

        {"type": "pagebreak"},
        h1("h_appB"), p("appB_purpose"), p("appB_need"),
        fig(f("fig_deploy.png"), 470, "fig9"), box("note", "c_who"), p("appB_english"),
        h2("h_b0"), p("b0_p"), nums("b0_steps"), box("note", "c_source"),
        h2("h_b1"), nums("b1_steps"), p("b1_success"),
        h2("h_b2"), nums("b2_steps"), fig(nf("fig_nf_projects.png"), 470, "fig10"), box("trap", "c_only_app"),
        h2("h_b3"), fig(nf("fig_nf_overview.png"), 420, "fig11"), tab("t_overview", [1, 4, 8]), p("b3_public"),
        h2("h_b4"), p("b4_p"), nums("b4_steps"),
        fig(nf("fig_nf_config.png"), 400, "fig12"), fig(nf("fig_nf_rename.png"), 300, "fig13"),
        box("note", "c_name_rules"), box("trap", "c_rename"),
        h2("h_b5"), p("b5_p"), nums("b5_steps"), fig(nf("fig_nf_visibility.png"), 420, "fig14"), box("tip", "c_make_public"),
        h2("h_b6"), p("b6_p"),
        h2("h_b7"), nums("b7_steps"), fig(nf("fig_nf_deploys.png"), 470, "fig15"), p("b7_success"), box("tip", "c_folder"),
        h2("h_b8"), tab("t_b8", [2, 3]),

        {"type": "pagebreak"},
        h1("h_appC"), p("appC_purpose"), tab("t_services", [2, 2, 5, 3]),
        box("trap", "c_subscription"), box("note", "c_cost"),
        h2("h_c1"), nums("c1_steps"),
        h2("h_c2"), nums("c2_steps"),
        h2("h_c3"), nums("c3_steps"),
        box("trap", "c_copy_key"),
        h2("h_c4"), nums("c4_steps"), fig(f("fig_aikey.png"), 260, "fig16"), p("c4_success"), box("tip", "c_switch"),

        h1("h_glossary"), tab("t_glossary", [1, 3]), p("revision"),
    ]


