# ── typography per language ──
def fr_typo(s):
    """French: non-breaking space before : ; ! ? and inside « » (not inside web addresses)."""
    s = re.sub(r" ([:;!?])(?=\s|$)", " \\1", s)
    return s.replace("« ", "« ").replace(" »", " »")


def de_typo(s):
    return s  # no quotation marks used in the German texts


def apply(obj, fn):
    if isinstance(obj, str):
        return fn(obj)
    if isinstance(obj, list):
        return [apply(x, fn) for x in obj]
    if isinstance(obj, tuple):
        return tuple(apply(x, fn) for x in obj)
    if isinstance(obj, dict):
        return {k: apply(v, fn) for k, v in obj.items()}
    return obj


BOX_LABELS = {"en": None,
              "fr": {"tip": "ASTUCE", "note": "À SAVOIR", "trap": "PIÈGE", "page": "Page"},
              "nl": {"tip": "TIP", "note": "LET OP", "trap": "VALKUIL", "page": "Pagina"},
              "de": {"tip": "TIPP", "note": "HINWEIS", "trap": "FALLE", "page": "Seite"}}

LANGS = {"en": EN, "fr": apply(FR, fr_typo), "nl": NL, "de": apply(DE, de_typo)}

if __name__ == "__main__":
    keys = set(EN) - {"meta"}
    for code, T in LANGS.items():
        missing = keys - set(T)
        extra = set(T) - keys - {"meta"}
        assert not missing and not extra, (code, sorted(missing), sorted(extra))
        meta = {
            "title": "Meal Planner",
            "subtitle": T["meta"]["subtitle"],
            "version": {"en": "Version 2.0", "fr": "Version 2.0", "nl": "Versie 2.0", "de": "Version 2.0"}[code],
            "date": T["meta"]["date"],
            "project": "Meal Planner",
            "author": "Hans Tandt",
            "tocTitle": T["meta"]["tocTitle"],
            "mascot": {"cover": "figures/mascot/cover.png", "coverWidth": 190, "tip": "figures/mascot/tip.png",
                       "note": "figures/mascot/note.png", "trap": "figures/mascot/trap.png", "width": 46},
        }
        if BOX_LABELS[code]:
            meta["labels"] = BOX_LABELS[code]
        out = {"meta": meta, "blocks": blocks(T, code)}
        path = HERE / f"content_{code.upper()}.json"
        path.write_text(json.dumps(out, ensure_ascii=False, indent=2), encoding="utf-8")
        print(path.name, len(out["blocks"]), "blocks")
